/*
 * A285955  Numbers a(n) = T(b(n))*sqrt(T(b(n))+1), where T(b(n)) is the
 *          triangular number of b(n)= A000217(b(n)) and b(n)=A006451(n). Also
 *          a(n) = y solutions of the Bachet Mordell equation y^2=x^3+K, where
 *          x= T(b(n)) = A006454(n) and K = (T(b(n)))^2= A285985(n).
 * https://oeis.org/A285955
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = T(b(n))*sqrt(T(b(n))+1); where b(n) are the integers
 *            satisfying b(b+1)/2 + 1 = k² (square), and are generated by the
 *            two interleaved Pell sequences (u + v√8) with initial solutions
 *            (u,v) = (1,1) and (5,2). The recurrence for the Pell solutions
 *            is u' = 3u + 8v, v' = u + 3v. b = (u-1)/2, k =...
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 8, u64 n <= 17, u128 n <= 33,
 *            big any n
 * Helpers:   next_pell_pair
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/next_pell_pair.h"

/* idx_t and seq_t are provided by the build environment; do not
   redefine them here. The function link must be external. */
extern seq_t a(idx_t n);

static seq_t *cache = NULL;
static size_t cache_cap = 0;
static size_t cache_len = 0;

/* Pell state for the two interleaved sequences */
static seq_t u0 = 0, v0 = 0;
static seq_t u1 = 0, v1 = 0;
static bool init_done = false;

static void init_sequences(void)
{
    if (init_done) return;
    /* initial solutions of u² – 8v² = –7 */
    u0 = 1; v0 = 1;          /* gives b = 0, k = 1  */
    u1 = 5; v1 = 2;          /* gives b = 2, k = 2  */
    init_done = true;
}

static void ensure_cache_capacity(size_t needed)
{
    if (cache_cap >= needed) return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < needed) new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) abort();
    cache = tmp;
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    init_sequences();

    size_t need = (size_t)n + 1;
    if (cache_len < need)
    {
        ensure_cache_capacity(need);
        while (cache_len <= n)
        {
            seq_t b0 = (u0 - (seq_t)1) / (seq_t)2;
            seq_t b1 = (u1 - (seq_t)1) / (seq_t)2;

            bool use0 = b0 <= b1;
            seq_t b   = use0 ? b0 : b1;
            seq_t k   = use0 ? v0 : v1;

            /* T(b) = b*(b+1)/2 */
            seq_t t   = (b * (b + (seq_t)1)) / (seq_t)2;
            seq_t val = t * k;

            cache[cache_len++] = val;

            if (use0)
                next_pell_pair(&u0, &v0);
            else
                next_pell_pair(&u1, &v1);
        }
    }

    return cache[(size_t)n];
}
